ALTER TABLE public.profile_private ADD COLUMN date_of_birth date, ADD COLUMN age_verified boolean NOT NULL DEFAULT false, ADD COLUMN meet_age_min integer, ADD COLUMN meet_age_max integer;
REVOKE INSERT,UPDATE ON public.profile_private FROM authenticated;
GRANT INSERT(user_id,gender,gender_other,date_of_birth,meet_age_min,meet_age_max),UPDATE(gender,gender_other,date_of_birth,meet_age_min,meet_age_max) ON public.profile_private TO authenticated;
CREATE FUNCTION public.validate_private_age() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF NEW.date_of_birth IS NOT NULL AND (NEW.date_of_birth>current_date-interval '18 years' OR NEW.date_of_birth<current_date-interval '120 years') THEN RAISE EXCEPTION 'Tagalong is for adults aged 18 and over.'; END IF; IF TG_OP='UPDATE' AND NEW.date_of_birth IS DISTINCT FROM OLD.date_of_birth THEN NEW.age_verified:=false; END IF; IF NEW.meet_age_min IS NOT NULL AND (NEW.meet_age_min<18 OR NEW.meet_age_min>120) OR NEW.meet_age_max IS NOT NULL AND (NEW.meet_age_max<coalesce(NEW.meet_age_min,18) OR NEW.meet_age_max>120) THEN RAISE EXCEPTION 'Choose an adult age bracket.'; END IF; RETURN NEW; END $$;
CREATE TRIGGER validate_private_age BEFORE INSERT OR UPDATE ON public.profile_private FOR EACH ROW EXECUTE FUNCTION public.validate_private_age();
CREATE FUNCTION public.demo_confirm_age(_dob date) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Sign in first'; END IF; IF NOT EXISTS(SELECT 1 FROM public.profile_private WHERE user_id=auth.uid() AND date_of_birth=_dob AND _dob<=current_date-interval '18 years') THEN RAISE EXCEPTION 'Confirm the adult birth date saved in your profile.'; END IF; UPDATE public.profile_private SET age_verified=true WHERE user_id=auth.uid(); UPDATE public.profiles SET verified=true,onboarded=true WHERE id=auth.uid(); END $$;
REVOKE ALL ON FUNCTION public.demo_confirm_age(date) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.demo_confirm_age(date) TO authenticated;
CREATE TABLE public.organisations(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),name text NOT NULL CHECK(length(name) BETWEEN 1 AND 100),slug text NOT NULL UNIQUE,description text NOT NULL DEFAULT '' CHECK(length(description)<=3000),logo_url text,visibility text NOT NULL DEFAULT 'open' CHECK(visibility IN('open','members','private')),question text NOT NULL DEFAULT 'Why would you like to join?' CHECK(length(question)<=500),allowed_domains text[] NOT NULL DEFAULT '{}',is_example boolean NOT NULL DEFAULT false);
GRANT SELECT ON public.organisations TO anon,authenticated; GRANT ALL ON public.organisations TO service_role; ALTER TABLE public.organisations ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.organisation_members(organisation_id uuid NOT NULL REFERENCES public.organisations(id) ON DELETE CASCADE,user_id uuid NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE,role text NOT NULL DEFAULT 'member' CHECK(role IN('member','admin')),PRIMARY KEY(organisation_id,user_id));
GRANT SELECT ON public.organisation_members TO authenticated; GRANT ALL ON public.organisation_members TO service_role; ALTER TABLE public.organisation_members ENABLE ROW LEVEL SECURITY;
CREATE FUNCTION public.org_member(_org uuid,_user uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM public.organisation_members WHERE organisation_id=_org AND user_id=_user) $$;
CREATE FUNCTION public.org_admin(_org uuid,_user uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM public.organisation_members WHERE organisation_id=_org AND user_id=_user AND role='admin') $$;
CREATE POLICY "visible organisations" ON public.organisations FOR SELECT USING(visibility<>'private' OR public.org_member(id,auth.uid()));
CREATE POLICY "own membership or admin" ON public.organisation_members FOR SELECT TO authenticated USING(user_id=auth.uid() OR public.org_admin(organisation_id,auth.uid()));
CREATE TABLE public.organisation_secrets(organisation_id uuid PRIMARY KEY REFERENCES public.organisations(id) ON DELETE CASCADE,passphrase_hash text);
GRANT ALL ON public.organisation_secrets TO service_role; ALTER TABLE public.organisation_secrets ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.organisation_requests(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),organisation_id uuid NOT NULL REFERENCES public.organisations(id) ON DELETE CASCADE,user_id uuid NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE,answer text NOT NULL CHECK(length(answer) BETWEEN 1 AND 2000),status text NOT NULL DEFAULT 'pending' CHECK(status IN('pending','approved','declined')),UNIQUE(organisation_id,user_id));
GRANT SELECT ON public.organisation_requests TO authenticated; GRANT ALL ON public.organisation_requests TO service_role; ALTER TABLE public.organisation_requests ENABLE ROW LEVEL SECURITY;
CREATE POLICY "requester and organisation admin" ON public.organisation_requests FOR SELECT TO authenticated USING(user_id=auth.uid() OR public.org_admin(organisation_id,auth.uid()));
CREATE TABLE public.organisation_follows(organisation_id uuid NOT NULL REFERENCES public.organisations(id) ON DELETE CASCADE,user_id uuid NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE,PRIMARY KEY(organisation_id,user_id));
GRANT SELECT,INSERT,DELETE ON public.organisation_follows TO authenticated; GRANT ALL ON public.organisation_follows TO service_role; ALTER TABLE public.organisation_follows ENABLE ROW LEVEL SECURITY;
CREATE POLICY "own organisation follows" ON public.organisation_follows FOR ALL TO authenticated USING(user_id=auth.uid()) WITH CHECK(user_id=auth.uid() AND EXISTS(SELECT 1 FROM public.organisations WHERE id=organisation_id));
CREATE TABLE public.organisation_email_checks(organisation_id uuid NOT NULL REFERENCES public.organisations(id) ON DELETE CASCADE,user_id uuid NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE,email text NOT NULL,code_hash text NOT NULL,expires_at timestamptz NOT NULL,attempts integer NOT NULL DEFAULT 0,PRIMARY KEY(organisation_id,user_id));
GRANT ALL ON public.organisation_email_checks TO service_role; ALTER TABLE public.organisation_email_checks ENABLE ROW LEVEL SECURITY;
CREATE FUNCTION public.org_access(_org uuid,_user uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT _org IS NULL OR EXISTS(SELECT 1 FROM public.organisations WHERE id=_org AND (visibility='open' OR public.org_member(id,_user))) $$;
ALTER TABLE public.plans ADD COLUMN age_min integer, ADD COLUMN age_max integer, ADD COLUMN organisation_id uuid REFERENCES public.organisations(id);
ALTER POLICY "plans are public" ON public.plans USING(NOT is_private AND public.org_access(organisation_id,auth.uid()));
ALTER POLICY "private plan participants read" ON public.plans USING(host_id=auth.uid() OR (is_private AND auth.uid()=ANY(private_participants) AND public.org_access(organisation_id,auth.uid())));
CREATE FUNCTION public.org_plan_teasers(_org uuid DEFAULT NULL,_plan uuid DEFAULT NULL) RETURNS TABLE(id uuid,title text,image_url text,area_label text,starts_at timestamptz,base_price numeric,organisation_id uuid,city text,genre text,activity text,is_example boolean,age_min integer,age_max integer) LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT p.id,p.title,p.image_url,p.area_label,p.starts_at,p.base_price,p.organisation_id,p.city,p.genre,p.activity,p.is_example,p.age_min,p.age_max FROM public.plans p JOIN public.organisations o ON o.id=p.organisation_id WHERE NOT p.is_private AND o.visibility='members' AND (_org IS NULL OR o.id=_org) AND (_plan IS NULL OR p.id=_plan) AND NOT public.org_access(o.id,auth.uid()) $$;
CREATE FUNCTION public.guard_v4_plan() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NEW.age_min IS NOT NULL AND (NEW.age_min<18 OR NEW.age_min>120) OR NEW.age_max IS NOT NULL AND (NEW.age_max<coalesce(NEW.age_min,18) OR NEW.age_max>120) THEN RAISE EXCEPTION 'Choose a valid adult age range.'; END IF; IF TG_OP='INSERT' AND NOT NEW.is_example AND NOT EXISTS(SELECT 1 FROM public.profile_private WHERE user_id=NEW.host_id AND age_verified AND date_of_birth<=current_date-interval '18 years') THEN RAISE EXCEPTION 'Complete demo age verification before hosting.'; END IF; IF NEW.organisation_id IS NOT NULL AND NOT NEW.is_example AND NOT public.org_admin(NEW.organisation_id,NEW.host_id) THEN RAISE EXCEPTION 'Only organisation admins can host on its behalf.'; END IF; RETURN NEW; END $$;
CREATE TRIGGER guard_v4_plan BEFORE INSERT OR UPDATE ON public.plans FOR EACH ROW EXECUTE FUNCTION public.guard_v4_plan();
CREATE FUNCTION public.guard_v4_join() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE p public.plans; dob date; verified boolean; years integer; BEGIN SELECT * INTO p FROM public.plans WHERE id=NEW.plan_id; SELECT date_of_birth,age_verified INTO dob,verified FROM public.profile_private WHERE user_id=NEW.user_id; IF dob IS NULL OR NOT coalesce(verified,false) OR dob>current_date-interval '18 years' THEN RAISE EXCEPTION 'Complete demo age verification before joining.'; END IF; years:=extract(year FROM age(p.starts_at::date,dob)); IF years<coalesce(p.age_min,18) OR years>coalesce(p.age_max,120) THEN RAISE EXCEPTION 'This plan is for a different age bracket. Try another welcoming plan.'; END IF; IF NOT public.org_access(p.organisation_id,NEW.user_id) THEN RAISE EXCEPTION 'Join this organisation before requesting its events.'; END IF; IF NEW.bring_buddy AND (p.age_min IS NOT NULL OR p.age_max IS NOT NULL OR p.organisation_id IS NOT NULL) THEN RAISE EXCEPTION 'For restricted plans, each person needs their own verified request.'; END IF; RETURN NEW; END $$;
CREATE TRIGGER guard_v4_join BEFORE INSERT ON public.join_requests FOR EACH ROW EXECUTE FUNCTION public.guard_v4_join();
CREATE FUNCTION public.request_org_access(_org uuid,_answer text) RETURNS text LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE ph text; result text:='pending'; BEGIN IF auth.uid() IS NULL OR length(trim(_answer)) NOT BETWEEN 1 AND 2000 OR NOT EXISTS(SELECT 1 FROM public.organisations WHERE id=_org AND visibility<>'private') THEN RAISE EXCEPTION 'Access request unavailable'; END IF; IF public.org_member(_org,auth.uid()) THEN RETURN 'approved'; END IF; SELECT passphrase_hash INTO ph FROM public.organisation_secrets WHERE organisation_id=_org; IF ph IS NOT NULL AND ph=encode(sha256(convert_to(trim(_answer),'UTF8')),'hex') THEN result:='approved'; END IF; INSERT INTO public.organisation_requests(organisation_id,user_id,answer,status) VALUES(_org,auth.uid(),trim(_answer),result) ON CONFLICT(organisation_id,user_id) DO UPDATE SET answer=excluded.answer,status=excluded.status; IF result='approved' THEN INSERT INTO public.organisation_members(organisation_id,user_id) VALUES(_org,auth.uid()) ON CONFLICT DO NOTHING; END IF; RETURN result; END $$;
CREATE FUNCTION public.edit_org(_org uuid,_description text,_visibility text,_question text,_domains text[],_passphrase text DEFAULT NULL) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NOT public.org_admin(_org,auth.uid()) THEN RAISE EXCEPTION 'Organisation admins only'; END IF; IF length(_description)>3000 OR length(_question)>500 OR _visibility NOT IN('open','members','private') OR cardinality(_domains)>20 OR length(coalesce(_passphrase,''))>200 THEN RAISE EXCEPTION 'Invalid organisation settings'; END IF; IF EXISTS(SELECT 1 FROM unnest(_domains) d WHERE d!~'^[a-z0-9.-]+\.[a-z]{2,}$') THEN RAISE EXCEPTION 'Use email domains without @'; END IF; UPDATE public.organisations SET description=_description,visibility=_visibility,question=_question,allowed_domains=_domains WHERE id=_org; IF _passphrase IS NOT NULL THEN INSERT INTO public.organisation_secrets VALUES(_org,CASE WHEN _passphrase='' THEN NULL ELSE encode(sha256(convert_to(trim(_passphrase),'UTF8')),'hex') END) ON CONFLICT(organisation_id) DO UPDATE SET passphrase_hash=excluded.passphrase_hash; END IF; END $$;
CREATE FUNCTION public.review_org_request(_request uuid,_approve boolean) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE r public.organisation_requests; BEGIN SELECT * INTO r FROM public.organisation_requests WHERE id=_request FOR UPDATE; IF NOT public.org_admin(r.organisation_id,auth.uid()) THEN RAISE EXCEPTION 'Organisation admins only'; END IF; UPDATE public.organisation_requests SET status=CASE WHEN _approve THEN 'approved' ELSE 'declined' END WHERE id=r.id; IF _approve THEN INSERT INTO public.organisation_members(organisation_id,user_id) VALUES(r.organisation_id,r.user_id) ON CONFLICT DO NOTHING; END IF; END $$;
CREATE FUNCTION public.remove_org_member(_org uuid,_user uuid) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NOT public.org_admin(_org,auth.uid()) OR _user=auth.uid() THEN RAISE EXCEPTION 'An admin can remove other members only'; END IF; DELETE FROM public.organisation_members WHERE organisation_id=_org AND user_id=_user AND role='member'; END $$;
CREATE FUNCTION public.start_org_email_demo(_org uuid,_email text) RETURNS text LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE code text; BEGIN IF auth.uid() IS NULL OR length(_email)>255 OR _email!~'^[^@\s]+@[^@\s]+$' OR NOT EXISTS(SELECT 1 FROM public.organisations WHERE id=_org AND visibility<>'private' AND lower(split_part(_email,'@',2))=ANY(allowed_domains)) THEN RAISE EXCEPTION 'Use an email on an allowed organisation domain.'; END IF; code:=lpad(floor(random()*1000000)::text,6,'0'); INSERT INTO public.organisation_email_checks(organisation_id,user_id,email,code_hash,expires_at) VALUES(_org,auth.uid(),lower(_email),encode(sha256(convert_to(code,'UTF8')),'hex'),now()+interval '10 minutes') ON CONFLICT(organisation_id,user_id) DO UPDATE SET email=excluded.email,code_hash=excluded.code_hash,expires_at=excluded.expires_at,attempts=0; RETURN code; END $$;
CREATE FUNCTION public.confirm_org_email_demo(_org uuid,_code text) RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE c public.organisation_email_checks; BEGIN IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Sign in first'; END IF; SELECT * INTO c FROM public.organisation_email_checks WHERE organisation_id=_org AND user_id=auth.uid() FOR UPDATE; IF c.user_id IS NULL OR c.expires_at<now() OR c.attempts>=5 THEN RETURN false; END IF; UPDATE public.organisation_email_checks SET attempts=attempts+1 WHERE organisation_id=_org AND user_id=auth.uid(); IF c.code_hash<>encode(sha256(convert_to(_code,'UTF8')),'hex') THEN RETURN false; END IF; INSERT INTO public.organisation_members(organisation_id,user_id) VALUES(_org,auth.uid()) ON CONFLICT DO NOTHING; DELETE FROM public.organisation_email_checks WHERE organisation_id=_org AND user_id=auth.uid(); RETURN true; END $$;
REVOKE ALL ON FUNCTION public.request_org_access(uuid,text),public.edit_org(uuid,text,text,text,text[],text),public.review_org_request(uuid,boolean),public.remove_org_member(uuid,uuid),public.start_org_email_demo(uuid,text),public.confirm_org_email_demo(uuid,text) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.request_org_access(uuid,text),public.edit_org(uuid,text,text,text,text[],text),public.review_org_request(uuid,boolean),public.remove_org_member(uuid,uuid),public.start_org_email_demo(uuid,text),public.confirm_org_email_demo(uuid,text) TO authenticated;
CREATE FUNCTION public.calendar_friend_plans() RETURNS TABLE(friend_id uuid,friend_name text,plan_id uuid,title text,starts_at timestamptz,duration_minutes integer,recurring_weekly boolean,image_url text,area_label text,city text,genre text) LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT j.user_id,split_part(pr.name,' ',1),p.id,p.title,p.starts_at,p.duration_minutes,p.recurring_weekly,p.image_url,p.area_label,p.city,p.genre FROM public.join_requests j JOIN public.plans p ON p.id=j.plan_id JOIN public.profiles pr ON pr.id=j.user_id WHERE auth.uid() IS NOT NULL AND j.status='approved' AND public.are_friends(auth.uid(),j.user_id) AND NOT public.people_blocked(auth.uid(),j.user_id) AND NOT p.is_private AND public.org_access(p.organisation_id,auth.uid()) $$;
REVOKE ALL ON FUNCTION public.calendar_friend_plans() FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.calendar_friend_plans() TO authenticated;